insert into public.site_settings (organization_id, slug, name, description)
select id, 'signal-to-story', '星火工厂 · Signal to Story', '企业 AI 实战、AI 知识科普、工具与工作流、故事与创意。'
from public.organizations where slug = 'signal-to-story'
on conflict (slug) do nothing;
-- <<< 20261116100000_create_site_publishing.sql

-- >>> 20261116100100_site_publish_functions.sql
-- Site publish / unpublish transactions (docs-site/spec/sense-site-SPEC.md, "数据发布边界").
--
-- Security review notes (SECURITY DEFINER is required because clients have no
-- write grant on site_entries / releases / bodies / events):
--   * search_path is pinned to '' and every object is schema-qualified.
--   * EXECUTE is revoked from PUBLIC and anon; only authenticated may call.
--   * Caller must be signed in, non-anonymous, and hold content.publish in the
--     site's organization (private.has_organization_permission).
--   * The source document row is locked and re-checked inside the transaction:
--     same organization, status = 'approved', current revision = requested
--     revision, and an 'approved' content_review_events row for that revision.
--     Title and body are copied from the immutable content_revisions row, never
--     from client input.
--   * Only display metadata (slug, summary, category, format, column, cover,
--     access level, media/source references) comes from the caller and is
--     validated against a whitelist; member / purchase access is rejected.
--   * Releases, bodies and events are append-only (immutability triggers).

create function private.site_validate_url(value text, allow_empty boolean default true) returns boolean
language sql immutable set search_path = '' as $$
  select case when value is null or value = '' then allow_empty
    else value ~ '^https://[^[:space:]<>"]+$' and char_length(value) <= 2000 end;
$$;
revoke all on function private.site_validate_url(text, boolean) from public, anon, authenticated;

create function public.publish_site_entry(
  p_site_id uuid,
  p_document_id uuid,
  p_revision integer,
  p_meta jsonb default '{}'::jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  v_site public.site_settings%rowtype;
  v_doc public.content_documents%rowtype;
  v_rev public.content_revisions%rowtype;
  v_entry public.site_entries%rowtype;
  v_current public.site_entry_releases%rowtype;
  v_release_id uuid;
  v_version integer;
  v_action text;
  v_meta jsonb;
  v_item jsonb;
  v_slug text := lower(btrim(coalesce(p_meta ->> 'slug', '')));
  v_summary text := btrim(coalesce(p_meta ->> 'summary', ''));
  v_format text := coalesce(nullif(p_meta ->> 'format', ''), 'article');
  v_column text := nullif(btrim(coalesce(p_meta ->> 'column_key', '')), '');
  v_access text := coalesce(nullif(p_meta ->> 'access_level', ''), 'public');
  v_category uuid;
  v_cover text := btrim(coalesce(p_meta ->> 'cover_url', ''));
  v_cover_alt text := btrim(coalesce(p_meta ->> 'cover_alt', ''));
  v_media jsonb := coalesce(p_meta -> 'media', '[]'::jsonb);
  v_refs jsonb := coalesce(p_meta -> 'source_refs', '[]'::jsonb);
begin
  if v_uid is null or coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false) then
    raise exception '需要登录后台账号' using errcode = '42501';
  end if;
  if p_meta is null or jsonb_typeof(p_meta) <> 'object' then
    raise exception '发布参数格式无效' using errcode = '22023';
  end if;

  select * into v_site from public.site_settings where id = p_site_id;
  if not found then raise exception '站点不存在' using errcode = 'P0002'; end if;
  if not private.has_organization_permission(v_site.organization_id, 'content.publish') then
    raise exception '需要该组织的站点发布权限' using errcode = '42501';
  end if;

  -- Lock the source document so review status cannot change mid-transaction.
  select * into v_doc from public.content_documents
  where id = p_document_id and organization_id = v_site.organization_id
  for update;
  if not found then raise exception '稿件不存在或不属于该站点所属组织' using errcode = '42501'; end if;
  if v_doc.status <> 'approved' or v_doc.revision <> p_revision then
    raise exception '仅可发布当前已人工审核通过的版本' using errcode = 'P0001';
  end if;
  if not exists (
    select 1 from public.content_review_events ev
    where ev.organization_id = v_doc.organization_id and ev.document_id = v_doc.id
      and ev.revision = p_revision and ev.status = 'approved'
  ) then
    raise exception '缺少该版本的人工审核通过记录' using errcode = 'P0001';
  end if;
  -- MANDATE HOOK (P1.5, public.approval_requests from 20261115100200_approval_requests_mandate.sql):
  -- when site publishing must also carry a database-level Mandate, add here:
  --   if not exists (select 1 from public.approval_requests a
  --     where a.organization_id = v_doc.organization_id and a.action = 'publish_site'
  --       and a.target_id = v_doc.id::text and a.target_revision = p_revision
  --       and a.status = 'approved' and a.expires_at > now()) then raise ... using errcode = '42501';
  -- (bind target_type / payload->>'site_id' per the final P1.5 convention). Until then the gate is the
  -- human review record above, which every publish already requires.

  select * into v_rev from public.content_revisions
  where organization_id = v_doc.organization_id and document_id = v_doc.id and revision = p_revision;
  if not found or btrim(v_rev.body) = '' then
    raise exception '已审核版本没有可发布的正文' using errcode = 'P0001';
  end if;

  -- Display metadata whitelist.
  if v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or char_length(v_slug) > 96 then
    raise exception '站点链接标识仅允许小写字母、数字和连字符（最多 96 字）' using errcode = '22023';
  end if;
  if char_length(v_summary) not between 1 and 500 then
    raise exception '请填写 1–500 字的人工摘要' using errcode = '22023';
  end if;
  if v_access not in ('public', 'registered') then
    raise exception '首版仅支持 public / registered 访问级别' using errcode = '22023';
  end if;
  if v_format not in ('article', 'tutorial', 'video', 'comic', 'resource') then
    raise exception '无效的内容形式' using errcode = '22023';
  end if;
  if v_column is not null and v_column not in ('news', 'analysis', 'how_to', 'case') then
    raise exception '无效的栏目' using errcode = '22023';
  end if;
  if not private.site_validate_url(v_cover) or char_length(v_cover_alt) > 200 or (v_cover <> '' and v_cover_alt = '') then
    raise exception '封面需为 https 地址并填写替代文本' using errcode = '22023';
  end if;
  if nullif(p_meta ->> 'category_id', '') is not null then
    begin
      v_category := (p_meta ->> 'category_id')::uuid;
    exception when invalid_text_representation then
      raise exception '无效的分类' using errcode = '22023';
    end;
    if not exists (select 1 from public.site_categories c where c.id = v_category and c.site_id = p_site_id and c.enabled) then
      raise exception '分类不存在或未启用' using errcode = '22023';
    end if;
  end if;
  if jsonb_typeof(v_media) <> 'array' or jsonb_array_length(v_media) > 20 then
    raise exception '媒体引用格式无效' using errcode = '22023';
  end if;
  for v_item in select value from jsonb_array_elements(v_media) loop
    if jsonb_typeof(v_item) <> 'object'
      or coalesce(v_item ->> 'kind', '') not in ('image', 'video')
      or not private.site_validate_url(v_item ->> 'url', false)
      or not private.site_validate_url(coalesce(v_item ->> 'poster', ''))
      or char_length(coalesce(v_item ->> 'alt', '')) > 200
      or (v_item ->> 'kind' = 'image' and btrim(coalesce(v_item ->> 'alt', '')) = '') then
      raise exception '媒体需为 https 地址，图片需填写替代文本' using errcode = '22023';
    end if;
  end loop;
  if v_format = 'video' and not exists (select 1 from jsonb_array_elements(v_media) m where m.value ->> 'kind' = 'video') then
    raise exception '视频内容需要提供视频地址' using errcode = '22023';
  end if;
  if jsonb_typeof(v_refs) <> 'array' or jsonb_array_length(v_refs) > 50 then
    raise exception '来源引用格式无效' using errcode = '22023';
  end if;
  for v_item in select value from jsonb_array_elements(v_refs) loop
    if jsonb_typeof(v_item) <> 'object'
      or char_length(btrim(coalesce(v_item ->> 'title', ''))) not between 1 and 200
      or not private.site_validate_url(v_item ->> 'url', false) then
      raise exception '来源引用需包含标题和 https 地址' using errcode = '22023';
    end if;
  end loop;

  v_meta := jsonb_build_object(
    'slug', v_slug, 'summary', v_summary, 'category_id', v_category, 'format', v_format,
    'column_key', v_column, 'cover_url', v_cover, 'cover_alt', v_cover_alt,
    'access_level', v_access, 'media', v_media, 'source_refs', v_refs);

  select * into v_entry from public.site_entries
  where site_id = p_site_id and source_document_id = v_doc.id
  for update;

  if exists (select 1 from public.site_entries e where e.site_id = p_site_id and e.slug = v_slug and e.id is distinct from v_entry.id) then
    raise exception '站点链接标识已被其他内容使用' using errcode = '23505';
  end if;

  -- Idempotent retry: same approved revision and same display metadata.
  if v_entry.id is not null and v_entry.status = 'online' then
    select * into v_current from public.site_entry_releases where id = v_entry.current_release_id;
    if v_current.source_revision = p_revision and v_current.display_meta = v_meta then
      return jsonb_build_object('entry_id', v_entry.id, 'release_id', v_current.id, 'version', v_current.version,
        'slug', v_entry.slug, 'action', 'unchanged', 'unchanged', true);
    end if;
  end if;

  if v_entry.id is null then
    insert into public.site_entries (organization_id, site_id, source_document_id, slug, title, summary, category_id,
      format, column_key, cover_url, cover_alt, access_level, status, current_version, published_at, updated_at)
    values (v_site.organization_id, p_site_id, v_doc.id, v_slug, v_rev.title, v_summary, v_category,
      v_format, v_column, v_cover, v_cover_alt, v_access, 'offline', 0, now(), now())
    returning * into v_entry;
    v_action := 'publish';
  elsif v_entry.status = 'offline' then
    v_action := 'republish';
  else
    v_action := 'replace';
  end if;
  v_version := v_entry.current_version + 1;

  insert into public.site_entry_releases (organization_id, site_id, entry_id, version, source_document_id,
    source_revision, source_platform, title, display_meta, published_by)
  values (v_site.organization_id, p_site_id, v_entry.id, v_version, v_doc.id, p_revision, v_doc.platform,
    v_rev.title, v_meta, v_uid)
  returning id into v_release_id;

  insert into public.site_entry_bodies (release_id, organization_id, site_id, entry_id, markdown, media, source_refs)
  values (v_release_id, v_site.organization_id, p_site_id, v_entry.id, v_rev.body, v_media, v_refs);

  update public.site_entries set
    slug = v_slug, title = v_rev.title, summary = v_summary, category_id = v_category, format = v_format,
    column_key = v_column, cover_url = v_cover, cover_alt = v_cover_alt, access_level = v_access,
    status = 'online', current_release_id = v_release_id, current_version = v_version,
    updated_at = now(), offline_at = null
  where id = v_entry.id;

  insert into public.site_release_events (organization_id, site_id, entry_id, release_id, action, actor_id)
  values (v_site.organization_id, p_site_id, v_entry.id, v_release_id, v_action, v_uid);

  insert into public.audit_events (organization_id, actor_user_id, action, target_type, target_id, metadata)
  values (v_site.organization_id, v_uid, 'site.entry.' || v_action, 'site_entry', v_entry.id::text,
    jsonb_build_object('release_id', v_release_id, 'document_id', v_doc.id, 'revision', p_revision, 'version', v_version));

  return jsonb_build_object('entry_id', v_entry.id, 'release_id', v_release_id, 'version', v_version,
    'slug', v_slug, 'action', v_action, 'unchanged', false);
end; $$;

create function public.unpublish_site_entry(p_entry_id uuid, p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  v_entry public.site_entries%rowtype;
begin
  if v_uid is null or coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false) then
    raise exception '需要登录后台账号' using errcode = '42501';
  end if;
  select * into v_entry from public.site_entries where id = p_entry_id for update;
  if not found then raise exception '站点内容不存在' using errcode = 'P0002'; end if;
  if not private.has_organization_permission(v_entry.organization_id, 'content.publish') then
    raise exception '需要该组织的站点发布权限' using errcode = '42501';
  end if;
  if char_length(coalesce(p_note, '')) > 1000 then
    raise exception '下线说明不超过 1000 字' using errcode = '22023';
  end if;
  if v_entry.status = 'offline' then
    return jsonb_build_object('entry_id', v_entry.id, 'status', 'offline', 'unchanged', true);
  end if;
  -- Offline is a state change; releases, bodies and bookmarks stay for audit.
  update public.site_entries set status = 'offline', offline_at = now(), updated_at = now() where id = v_entry.id;
  insert into public.site_release_events (organization_id, site_id, entry_id, release_id, action, note, actor_id)
  values (v_entry.organization_id, v_entry.site_id, v_entry.id, v_entry.current_release_id, 'unpublish', coalesce(p_note, ''), v_uid);
  insert into public.audit_events (organization_id, actor_user_id, action, target_type, target_id, metadata)
  values (v_entry.organization_id, v_uid, 'site.entry.unpublish', 'site_entry', v_entry.id::text,
    jsonb_build_object('release_id', v_entry.current_release_id));
  return jsonb_build_object('entry_id', v_entry.id, 'status', 'offline', 'unchanged', false);
end; $$;

revoke all on function public.publish_site_entry(uuid, uuid, integer, jsonb) from public, anon, authenticated;
revoke all on function public.unpublish_site_entry(uuid, text) from public, anon, authenticated;
grant execute on function public.publish_site_entry(uuid, uuid, integer, jsonb) to authenticated;
grant execute on function public.unpublish_site_entry(uuid, text) to authenticated;
-- <<< 20261116100100_site_publish_functions.sql

-- >>> 20261117100000_capture.sql
-- Capture (docs/database.md §4.1, DB2b): one core for every entrance.
--
--   capture_only : record one intake_events row; it waits in the inbox.
--   auto_draft   : the same row, plus in one transaction a work_items card, a master document and one
--                  document per requested platform, and one content_draft job per document.
--
-- Identity model
-- * Browser: public.quick_capture(...) runs with the caller's JWT. Requires content.manage;
--   auto_draft also requires agent.dispatch (enqueue_agent_job re-checks it).
-- * Trusted server (intake-gateway, im-webhook): public.quick_capture_for_connection(token_hash, input) and
--   public.accept_intake(token_hash, input) are service_role only. Organization and acting user come from the
--   intake connection, never from the request; the connection creator must still hold content.manage
--   (+ agent.dispatch for auto_draft). For auto_draft the call binds auth.uid() to that user (only the `sub`
--   claim; role stays service_role, so human-only actions such as decide_approval_request stay impossible)
--   and restores the claims afterwards.
-- * Dedupe is the intake_events key: (organization, source, connection, external_id). A retry with the same
--   key and the same input returns the first result; the same key with different input is a conflict.

-- Worker records the optional URL fetch as its own audit step (round 0).
alter table public.agent_job_steps drop constraint agent_job_steps_step_kind_check;
alter table public.agent_job_steps add constraint agent_job_steps_step_kind_check
 check (step_kind in ('context','fetch','generate','precheck','evaluate','persist'));

create function private.capture_platform_label(p text) returns text
language sql immutable set search_path='' as $$
 select case p when 'master' then '母稿' when 'wechat_channels' then '视频号' when 'wechat_official' then '公众号'
  when 'xiaohongshu' then '小红书' when 'douyin' then '抖音' when 'x' then 'X' when 'youtube' then 'YouTube'
  when 'reddit' then 'Reddit' else p end
$$;

-- Validate and normalize user input. Raises 22023 'invalid_input: …'.
create function private.capture_normalize(p_url text, p_note text, p_title text, p_intent text, p_platforms text[])
returns jsonb language plpgsql immutable set search_path='' as $$
declare
 url text := nullif(btrim(coalesce(p_url,'')),'');
 note text := nullif(btrim(coalesce(p_note,'')),'');
 title text := nullif(btrim(regexp_replace(coalesce(p_title,''),'\s+',' ','g')),'');
 platforms text[];
 p text;
begin
 if p_intent is null or p_intent not in ('capture_only','auto_draft') then
  raise exception 'invalid_input: intent 必须是 capture_only 或 auto_draft' using errcode='22023';
 end if;
 if url is null and note is null then raise exception 'invalid_input: 请提供链接或一句话想法' using errcode='22023'; end if;
 if url is not null and (char_length(url) > 512 or url !~* '^https?://[^/?#[:space:]@]+([/?#][^[:space:]]*)?$') then
  raise exception 'invalid_input: 链接必须是不含凭证的 http(s) 地址（≤512 字符）' using errcode='22023';
 end if;
 if note is not null and char_length(note) > 4000 then raise exception 'invalid_input: 备注最多 4000 字' using errcode='22023'; end if;
 if title is not null and char_length(title) > 64 then raise exception 'invalid_input: 标题最多 64 字' using errcode='22023'; end if;
 if title is null then
  title := left(btrim(regexp_replace(coalesce(note, regexp_replace(url,'^https?://','','i')),'\s+',' ','g')), 64);
 end if;
 platforms := array[]::text[];
 if p_intent = 'auto_draft' then
  foreach p in array coalesce(p_platforms, array[]::text[]) loop
   if p not in ('wechat_channels','wechat_official','xiaohongshu','douyin','x','youtube','reddit') then
    raise exception 'invalid_input: 不支持的平台 %', p using errcode='22023';
   end if;
   if not p = any(platforms) then platforms := platforms || p; end if;
  end loop;
 end if;
 return jsonb_build_object('url', url, 'note', note, 'title', title, 'intent', p_intent, 'platforms', to_jsonb(platforms));
end; $$;

-- Result of an existing capture, rebuilt from the rows it created (intake_events stays immutable).
create function private.capture_result(e public.intake_events, p_duplicate boolean) returns jsonb
language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
  'event_id', e.id, 'intent', e.payload->'input'->>'intent', 'duplicate', p_duplicate,
  'work_item_id', e.work_item_id,
  'documents', coalesce((
   select jsonb_agg(jsonb_build_object('platform', d.platform, 'document_id', d.id,
     'job_id', (select j.id from public.agent_jobs j where j.organization_id = d.organization_id
                and j.idempotency_key = 'capture:' || e.id || ':' || d.platform))
     order by d.platform = 'master' desc, d.platform)
   from public.content_documents d where d.organization_id = e.organization_id and d.work_item_id = e.work_item_id
  ), '[]'::jsonb),
  'inbox_path', '/intake',
  'item_path', case when e.work_item_id is null then null else '/work-items/' || e.work_item_id end)
$$;

-- Core pipeline. Caller has authenticated the actor (browser JWT or connection) and normalized the input.
create function private.capture_core(
 p_organization_id uuid, p_source text, p_connection_id uuid, p_external_id text, p_input jsonb, p_extra jsonb default '{}'::jsonb
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
 existing public.intake_events;
 ev public.intake_events;
 item uuid; doc uuid; job public.agent_jobs;
 url text := p_input->>'url'; note text := p_input->>'note'; title text := p_input->>'title';
 intent text := p_input->>'intent';
 platform text; instruction text;
begin
 if auth.uid() is not null and not private.has_organization_permission(p_organization_id,'content.manage') then
  raise exception '没有内容管理权限' using errcode='42501';
 end if;
 if intent = 'auto_draft' and not private.has_organization_permission(p_organization_id,'agent.dispatch') then
  raise exception '没有调度 Agent 任务的权限' using errcode='42501';
 end if;

 -- Serialize retries of the same key, then dedupe.
 perform pg_advisory_xact_lock(hashtextextended(concat_ws(':', p_organization_id, p_source, p_connection_id, p_external_id), 0));
 select * into existing from public.intake_events e
 where e.organization_id = p_organization_id and e.source = p_source
   and e.connection_id is not distinct from p_connection_id and e.external_id = p_external_id;
 if found then
  if existing.payload->'input' is distinct from p_input then raise exception 'idempotency_conflict' using errcode='23505'; end if;
  return private.capture_result(existing, true);
 end if;

 if p_connection_id is not null then
  if (select count(*) from public.intake_events where connection_id = p_connection_id and created_at > now() - interval '1 hour') >= 100 then
   raise exception 'rate_limited' using errcode='P0001';
  end if;
 elsif (select count(*) from public.intake_events where created_by = auth.uid() and created_at > now() - interval '1 hour') >= 120 then
  raise exception 'rate_limited' using errcode='P0001';
 end if;

 ev := public.record_intake_event(p_organization_id, p_source, p_external_id,
  concat_ws(E'\n\n', title, note), url,
  jsonb_build_object('input', p_input, 'intent', intent) || coalesce(p_extra, '{}'::jsonb), p_connection_id);

 if intent = 'auto_draft' then
  insert into public.work_items(organization_id, kind, title, brief, status, created_by)
  values (p_organization_id, 'article', title,
   jsonb_strip_nulls(jsonb_build_object('text', note, 'url', url, 'platforms', p_input->'platforms', 'intake_event_id', ev.id)),
   'doing', auth.uid())
  returning id into item;
  update public.intake_events set work_item_id = item where id = ev.id returning * into ev;

  foreach platform in array array['master'] || array(select jsonb_array_elements_text(p_input->'platforms')) loop
   insert into public.content_documents(organization_id, work_item_id, platform, title, body)
   values (p_organization_id, item, platform, title, '') returning id into doc;
   instruction := format('根据速记信源撰写%s初稿。%s', private.capture_platform_label(platform),
    coalesce('用户角度/备注：' || note, '用户只提供了链接，请围绕信源核心信息展开，无法确认的事实标注 [待核实]。'));
   job := public.enqueue_agent_job(p_organization_id, 'content_draft', 'capture:' || ev.id || ':' || platform,
    jsonb_build_object('document_id', doc, 'instruction', instruction, 'source', 'capture',
     'intake_event_id', ev.id, 'fetch_source', url is not null),
    'content_document', doc::text, 1);
  end loop;
 end if;

 insert into public.audit_events(organization_id, actor_user_id, action, target_type, target_id, metadata)
 values (p_organization_id, auth.uid(), 'intake.captured', 'intake_event', ev.id::text,
  jsonb_build_object('intent', intent, 'source', p_source, 'work_item_id', item));
 return private.capture_result(ev, false);
end; $$;
revoke all on function private.capture_platform_label(text) from public, anon, authenticated;
revoke all on function private.capture_normalize(text,text,text,text,text[]) from public, anon, authenticated;
revoke all on function private.capture_result(public.intake_events, boolean) from public, anon, authenticated;
revoke all on function private.capture_core(uuid,text,uuid,text,jsonb,jsonb) from public, anon, authenticated;

-- Browser entry.
create function public.quick_capture(
 p_organization_id uuid, p_url text, p_note text, p_intent text, p_platforms text[], p_idempotency_key text,
 p_title text default null
) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or auth.role() is distinct from 'authenticated' then
  raise exception '需要登录' using errcode='42501';
 end if;
 if p_idempotency_key is null or char_length(p_idempotency_key) not between 8 and 200 then
  raise exception 'invalid_input: 幂等键无效' using errcode='22023';
 end if;
 return private.capture_core(p_organization_id, 'web', null, p_idempotency_key,
  private.capture_normalize(p_url, p_note, p_title, p_intent, p_platforms));
end; $$;
revoke all on function public.quick_capture(uuid,text,text,text,text[],text,text) from public, anon;
grant execute on function public.quick_capture(uuid,text,text,text,text[],text,text) to authenticated;

-- Shared by every trusted-server entrance. Input:
-- {version:1, intent:'capture'|'capture_only'|'auto_draft', external_id, text, title?, url?, angle?, platforms?[]}
create function private.capture_for_connection(p_connection public.intake_connections, p_source text, p_input jsonb, p_extra jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 c public.intake_connections := p_connection;
 old_claims text := current_setting('request.jwt.claims', true);
 old_sub text := current_setting('request.jwt.claim.sub', true);
 intent text := case when p_input->>'intent' in ('capture','capture_only') then 'capture_only' else p_input->>'intent' end;
 normalized jsonb; result jsonb; note text;
begin
 if c.id is null or c.revoked_at is not null or c.expires_at <= now() then
  raise exception 'invalid_connection' using errcode='28000';
 end if;
 if jsonb_typeof(p_input) is distinct from 'object' or (p_input->>'version') is distinct from '1'
  or intent not in ('capture_only','auto_draft')
  or coalesce(char_length(btrim(p_input->>'external_id')),0) not between 1 and 128
  or coalesce(char_length(btrim(p_input->>'text')),0) not between 1 and 4000
  or coalesce(char_length(p_input->>'angle'),0) > 512
  or (p_input ? 'platforms' and jsonb_typeof(p_input->'platforms') <> 'array') then
  raise exception 'invalid_input' using errcode='22023';
 end if;
 -- The connection only works while its creator may still manage content.
 if not exists (select 1 from public.organization_members m join public.organization_roles r
   on r.organization_id = m.organization_id and r.role_key = m.role
   where m.organization_id = c.organization_id and m.user_id = c.created_by and 'content.manage' = any(r.permissions)) then
  raise exception 'invalid_connection' using errcode='28000';
 end if;
 note := btrim(p_input->>'text') || coalesce(E'\n角度：' || nullif(btrim(p_input->>'angle'),''), '');
 begin
  normalized := private.capture_normalize(p_input->>'url', note, p_input->>'title', intent,
   array(select jsonb_array_elements_text(coalesce(p_input->'platforms','[]'::jsonb))));
 exception when sqlstate '22023' then
  raise exception 'invalid_input' using errcode='22023';
 end;
 if intent = 'auto_draft' then
  -- Act as the connection's creator for this call only (sub claim; role is left untouched).
  perform set_config('request.jwt.claims', (coalesce(nullif(old_claims,''),'{}')::jsonb || jsonb_build_object('sub', c.created_by))::text, true);
  perform set_config('request.jwt.claim.sub', c.created_by::text, true);
 end if;
 begin
  result := private.capture_core(c.organization_id, p_source, c.id, btrim(p_input->>'external_id'), normalized, p_extra);
 exception when sqlstate '42501' then
  raise exception 'invalid_connection' using errcode='28000';
 end;
 perform set_config('request.jwt.claims', coalesce(old_claims,''), true);
 perform set_config('request.jwt.claim.sub', coalesce(old_sub,''), true);
 return result;
end; $$;
revoke all on function private.capture_for_connection(public.intake_connections, text, jsonb, jsonb) from public, anon, authenticated;

create function public.quick_capture_for_connection(p_token_hash text, p_input jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare c public.intake_connections;
begin
 select * into c from public.intake_connections where token_hash = p_token_hash for update;
 return private.capture_for_connection(c, 'api', p_input, '{}'::jsonb);
end; $$;
revoke all on function public.quick_capture_for_connection(text,jsonb) from public, anon, authenticated;
grant execute on function public.quick_capture_for_connection(text,jsonb) to service_role;

-- V1 external entrance (applied in 20261006131202), kept for the deployed intake-gateway: same input,
-- now lands in the inbox instead of creating a signal + selection.
create or replace function public.accept_intake(p_token_hash text, p_input jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r jsonb;
begin
 if (p_input->>'intent') is distinct from 'capture'
  or coalesce(char_length(btrim(p_input->>'title')),0) not between 1 and 64
  or coalesce(char_length(p_input->>'url'),0) > 512 then
  raise exception 'invalid_input' using errcode='22023';
 end if;
 r := public.quick_capture_for_connection(p_token_hash, (p_input - 'platforms') || jsonb_build_object('intent', 'capture_only'));
 return jsonb_build_object('receipt_id', r->'event_id', 'event_id', r->'event_id', 'duplicate', r->'duplicate',
  'status', 'captured', 'topic_path', r->>'inbox_path');
end; $$;
revoke all on function public.accept_intake(text,jsonb) from public, anon, authenticated;
grant execute on function public.accept_intake(text,jsonb) to service_role;
-- <<< 20261117100000_capture.sql

-- >>> 20261119100000_site_publish_mandate.sql
-- Enable the database-level Mandate for site publishing (hook left in 20261116100100).
-- publish_site_entry now additionally requires an approval_requests row: action = 'publish_site',
-- target_type = 'content_document', target_id = document id, target_revision = published revision,
-- payload.site_id = site, status = 'approved' and not expired. Errors: MD001 (missing / pending), MD002 (expired).
-- Revision bumps already expire older approvals (document_expire_approvals trigger). The approving human needs
-- content.publish (private.approval_required_permission). Grants are unchanged by CREATE OR REPLACE.

create or replace function public.publish_site_entry(
  p_site_id uuid,
  p_document_id uuid,
  p_revision integer,
  p_meta jsonb default '{}'::jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  v_site public.site_settings%rowtype;
  v_doc public.content_documents%rowtype;
  v_rev public.content_revisions%rowtype;
  v_entry public.site_entries%rowtype;
  v_current public.site_entry_releases%rowtype;
  v_release_id uuid;
  v_version integer;
  v_action text;
  v_meta jsonb;
  v_item jsonb;
  v_slug text := lower(btrim(coalesce(p_meta ->> 'slug', '')));
  v_summary text := btrim(coalesce(p_meta ->> 'summary', ''));
  v_format text := coalesce(nullif(p_meta ->> 'format', ''), 'article');
  v_column text := nullif(btrim(coalesce(p_meta ->> 'column_key', '')), '');
  v_access text := coalesce(nullif(p_meta ->> 'access_level', ''), 'public');
  v_category uuid;
  v_cover text := btrim(coalesce(p_meta ->> 'cover_url', ''));
  v_cover_alt text := btrim(coalesce(p_meta ->> 'cover_alt', ''));
  v_media jsonb := coalesce(p_meta -> 'media', '[]'::jsonb);
  v_refs jsonb := coalesce(p_meta -> 'source_refs', '[]'::jsonb);
begin
  if v_uid is null or coalesce(((select auth.jwt()) ->> 'is_anonymous')::boolean, false) then
    raise exception '需要登录后台账号' using errcode = '42501';
  end if;
  if p_meta is null or jsonb_typeof(p_meta) <> 'object' then
    raise exception '发布参数格式无效' using errcode = '22023';
  end if;

  select * into v_site from public.site_settings where id = p_site_id;
  if not found then raise exception '站点不存在' using errcode = 'P0002'; end if;
  if not private.has_organization_permission(v_site.organization_id, 'content.publish') then
    raise exception '需要该组织的站点发布权限' using errcode = '42501';
  end if;

  -- Lock the source document so review status cannot change mid-transaction.
  select * into v_doc from public.content_documents
  where id = p_document_id and organization_id = v_site.organization_id
  for update;
  if not found then raise exception '稿件不存在或不属于该站点所属组织' using errcode = '42501'; end if;
  if v_doc.status <> 'approved' or v_doc.revision <> p_revision then
    raise exception '仅可发布当前已人工审核通过的版本' using errcode = 'P0001';
  end if;
  if not exists (
    select 1 from public.content_review_events ev
    where ev.organization_id = v_doc.organization_id and ev.document_id = v_doc.id
      and ev.revision = p_revision and ev.status = 'approved'
  ) then
    raise exception '缺少该版本的人工审核通过记录' using errcode = 'P0001';
  end if;
  select * into v_rev from public.content_revisions
  where organization_id = v_doc.organization_id and document_id = v_doc.id and revision = p_revision;
  if not found or btrim(v_rev.body) = '' then
    raise exception '已审核版本没有可发布的正文' using errcode = 'P0001';
  end if;

  -- Display metadata whitelist.
  if v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or char_length(v_slug) > 96 then
    raise exception '站点链接标识仅允许小写字母、数字和连字符（最多 96 字）' using errcode = '22023';
  end if;
  if char_length(v_summary) not between 1 and 500 then
    raise exception '请填写 1–500 字的人工摘要' using errcode = '22023';
  end if;
  if v_access not in ('public', 'registered') then
    raise exception '首版仅支持 public / registered 访问级别' using errcode = '22023';
  end if;
  if v_format not in ('article', 'tutorial', 'video', 'comic', 'resource') then
    raise exception '无效的内容形式' using errcode = '22023';
  end if;
  if v_column is not null and v_column not in ('news', 'analysis', 'how_to', 'case') then
    raise exception '无效的栏目' using errcode = '22023';
  end if;
  if not private.site_validate_url(v_cover) or char_length(v_cover_alt) > 200 or (v_cover <> '' and v_cover_alt = '') then
    raise exception '封面需为 https 地址并填写替代文本' using errcode = '22023';
  end if;
  if nullif(p_meta ->> 'category_id', '') is not null then
    begin
      v_category := (p_meta ->> 'category_id')::uuid;
    exception when invalid_text_representation then
      raise exception '无效的分类' using errcode = '22023';
    end;
    if not exists (select 1 from public.site_categories c where c.id = v_category and c.site_id = p_site_id and c.enabled) then
      raise exception '分类不存在或未启用' using errcode = '22023';
    end if;
  end if;
  if jsonb_typeof(v_media) <> 'array' or jsonb_array_length(v_media) > 20 then
    raise exception '媒体引用格式无效' using errcode = '22023';
  end if;
  for v_item in select value from jsonb_array_elements(v_media) loop
    if jsonb_typeof(v_item) <> 'object'
      or coalesce(v_item ->> 'kind', '') not in ('image', 'video')
      or not private.site_validate_url(v_item ->> 'url', false)
      or not private.site_validate_url(coalesce(v_item ->> 'poster', ''))
      or char_length(coalesce(v_item ->> 'alt', '')) > 200
      or (v_item ->> 'kind' = 'image' and btrim(coalesce(v_item ->> 'alt', '')) = '') then
      raise exception '媒体需为 https 地址，图片需填写替代文本' using errcode = '22023';
    end if;
  end loop;
  if v_format = 'video' and not exists (select 1 from jsonb_array_elements(v_media) m where m.value ->> 'kind' = 'video') then
    raise exception '视频内容需要提供视频地址' using errcode = '22023';
  end if;
  if jsonb_typeof(v_refs) <> 'array' or jsonb_array_length(v_refs) > 50 then
    raise exception '来源引用格式无效' using errcode = '22023';
  end if;
  for v_item in select value from jsonb_array_elements(v_refs) loop
    if jsonb_typeof(v_item) <> 'object'
      or char_length(btrim(coalesce(v_item ->> 'title', ''))) not between 1 and 200
      or not private.site_validate_url(v_item ->> 'url', false) then
      raise exception '来源引用需包含标题和 https 地址' using errcode = '22023';
    end if;
  end loop;

  v_meta := jsonb_build_object(
    'slug', v_slug, 'summary', v_summary, 'category_id', v_category, 'format', v_format,
    'column_key', v_column, 'cover_url', v_cover, 'cover_alt', v_cover_alt,
    'access_level', v_access, 'media', v_media, 'source_refs', v_refs);

  select * into v_entry from public.site_entries
  where site_id = p_site_id and source_document_id = v_doc.id
  for update;

  if exists (select 1 from public.site_entries e where e.site_id = p_site_id and e.slug = v_slug and e.id is distinct from v_entry.id) then
    raise exception '站点链接标识已被其他内容使用' using errcode = '23505';
  end if;

  -- Idempotent retry: same approved revision and same display metadata.
  if v_entry.id is not null and v_entry.status = 'online' then
    select * into v_current from public.site_entry_releases where id = v_entry.current_release_id;
    if v_current.source_revision = p_revision and v_current.display_meta = v_meta then
      return jsonb_build_object('entry_id', v_entry.id, 'release_id', v_current.id, 'version', v_current.version,
        'slug', v_entry.slug, 'action', 'unchanged', 'unchanged', true);
    end if;
  end if;

  -- Database-level Mandate: a human-approved publish_site request bound to this document, revision and site.
  -- Placed after the idempotent short-circuit so a retry of an already-published snapshot never needs a fresh approval.
  if not exists (
    select 1 from public.approval_requests a
    where a.organization_id = v_doc.organization_id and a.action = 'publish_site'
      and a.target_type = 'content_document' and a.target_id = v_doc.id::text
      and a.target_revision = p_revision and a.payload ->> 'site_id' = p_site_id::text
      and a.status = 'approved' and a.expires_at > now()
  ) then
    if exists (
      select 1 from public.approval_requests a
      where a.organization_id = v_doc.organization_id and a.action = 'publish_site'
        and a.target_type = 'content_document' and a.target_id = v_doc.id::text
        and a.target_revision = p_revision and a.payload ->> 'site_id' = p_site_id::text
        and (a.status = 'expired' or (a.status = 'approved' and a.expires_at <= now()))
    ) then
      raise exception '发布批准已过期，请重新请求批准' using errcode = 'MD002';
    end if;
    raise exception '缺少该版本的有效发布批准，请先请求并获得批准' using errcode = 'MD001';
  end if;

  if v_entry.id is null then
    insert into public.site_entries (organization_id, site_id, source_document_id, slug, title, summary, category_id,
      format, column_key, cover_url, cover_alt, access_level, status, current_version, published_at, updated_at)
    values (v_site.organization_id, p_site_id, v_doc.id, v_slug, v_rev.title, v_summary, v_category,
      v_format, v_column, v_cover, v_cover_alt, v_access, 'offline', 0, now(), now())
    returning * into v_entry;
    v_action := 'publish';
  elsif v_entry.status = 'offline' then
    v_action := 'republish';
  else
    v_action := 'replace';
  end if;
  v_version := v_entry.current_version + 1;

  insert into public.site_entry_releases (organization_id, site_id, entry_id, version, source_document_id,
    source_revision, source_platform, title, display_meta, published_by)
  values (v_site.organization_id, p_site_id, v_entry.id, v_version, v_doc.id, p_revision, v_doc.platform,
    v_rev.title, v_meta, v_uid)
  returning id into v_release_id;

  insert into public.site_entry_bodies (release_id, organization_id, site_id, entry_id, markdown, media, source_refs)
  values (v_release_id, v_site.organization_id, p_site_id, v_entry.id, v_rev.body, v_media, v_refs);

  update public.site_entries set
    slug = v_slug, title = v_rev.title, summary = v_summary, category_id = v_category, format = v_format,
    column_key = v_column, cover_url = v_cover, cover_alt = v_cover_alt, access_level = v_access,
    status = 'online', current_release_id = v_release_id, current_version = v_version,
    updated_at = now(), offline_at = null
  where id = v_entry.id;

  insert into public.site_release_events (organization_id, site_id, entry_id, release_id, action, actor_id)
  values (v_site.organization_id, p_site_id, v_entry.id, v_release_id, v_action, v_uid);

  insert into public.audit_events (organization_id, actor_user_id, action, target_type, target_id, metadata)
  values (v_site.organization_id, v_uid, 'site.entry.' || v_action, 'site_entry', v_entry.id::text,
    jsonb_build_object('release_id', v_release_id, 'document_id', v_doc.id, 'revision', p_revision, 'version', v_version));

  return jsonb_build_object('entry_id', v_entry.id, 'release_id', v_release_id, 'version', v_version,
    'slug', v_slug, 'action', v_action, 'unchanged', false);
end; $$;

-- Planned publications are pinned to a document revision. When the document is saved as a new revision,
-- older planned rows are cancelled with invalidated_at set, so the schedule can never point at stale text.
-- (Recording a stale plan as published is already refused by guard_cloud_content.)
alter table public.content_publications add column invalidated_at timestamptz;

create function private.invalidate_stale_publications() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.revision > old.revision then
    update public.content_publications set status = 'cancelled', invalidated_at = now()
    where organization_id = new.organization_id and document_id = new.id
      and status = 'planned' and revision < new.revision;
  end if;
  return new;
end; $$;
revoke all on function private.invalidate_stale_publications() from public, anon, authenticated;
create trigger document_invalidate_publications after update on public.content_documents
  for each row execute function private.invalidate_stale_publications();
-- <<< 20261119100000_site_publish_mandate.sql

-- >>> 20261120100000_video_studio.sql
-- P5 Video Studio: storyboard plans/shots, storyboard proposals, cost ledger, private media bucket.
-- * Browser: read via RLS (content.view); author shots via column grants (content.manage).
-- * Any storyboard content change bumps video_plans.revision exactly once per statement.
-- * Worker (service_role) may only write render state / asset references / ledger rows, never content.
-- * Shots are locked while any shot of the plan (or the plan's composition) is rendering.
-- Rendering jobs, cost rules and the Mandate are in 20261120100100_video_studio_mandate.sql.

-- Generated media is registered in the existing asset ledger under one dedicated type.
alter table public.assets drop constraint assets_asset_type_check;
alter table public.assets add constraint assets_asset_type_check
  check (asset_type in ('character', 'scene', 'prop', 'sound', 'style', 'video_studio'));
comment on column public.assets.asset_type is '业务分类：character/scene/prop/sound/style；video_studio = 视频工坊生成物（category: keyframe/voiceover/shot_clip/final_video）。';

create table public.video_plans (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null references public.organizations(id) on delete cascade,
 project_id uuid,
 source_document_id uuid,
 source_document_revision integer,
 title text not null check (char_length(btrim(title)) between 1 and 160),
 aspect_ratio text not null default '9:16' check (aspect_ratio in ('9:16','16:9','1:1')),
 target_seconds integer not null default 30 check (target_seconds between 3 and 600),
 style text not null default '' check (char_length(style) <= 1000),
 default_voice text not null default 'zh-CN-XiaoxiaoNeural' check (char_length(default_voice) between 1 and 80),
 tts_provider text not null default 'edge_tts' check (tts_provider in ('edge_tts','cloud_tts')),
 bgm_track text check (bgm_track is null or char_length(bgm_track) <= 300),
 status text not null default 'draft' check (status in ('draft','rendering','rendered','failed','archived')),
 revision integer not null default 1 check (revision >= 1),
 composed_video_asset_id bigint,
 final_duration_ms integer check (final_duration_ms is null or final_duration_ms >= 0),
 error text check (error is null or char_length(error) <= 4000),
 source_proposal_id uuid,
 created_by uuid not null default auth.uid() references auth.users(id),
 updated_by uuid references auth.users(id),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 unique (organization_id, id),
 -- Composite asset FKs: an asset can only be referenced inside its own organization (assets_org_id_cloud_key).
 foreign key (organization_id, composed_video_asset_id) references public.assets(organization_id, id) on delete set null (composed_video_asset_id),
 foreign key (organization_id, project_id) references public.content_projects(organization_id, id),
 foreign key (organization_id, source_document_id, source_document_revision)
  references public.content_revisions(organization_id, document_id, revision)
);
comment on table public.video_plans is '视频工坊分镜计划。任何分镜内容变化都会递增 revision；付费渲染批准绑定 (video_plan, id, revision)。';

create table public.video_shots (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null,
 plan_id uuid not null,
 position integer not null check (position between 1 and 200),
 shot_size text not null default 'medium' check (shot_size in ('extreme_wide','wide','full','medium','close_up','extreme_close_up')),
 camera_motion text not null default 'zoom_in' check (camera_motion in ('zoom_in','zoom_out','pan_left','pan_right','pan_up','static')),
 motion_mode text not null default 'local_ken_burns' check (motion_mode in ('local_ken_burns','cloud_video_model')),
 visual_prompt text not null default '' check (char_length(visual_prompt) <= 2000),
 narration text not null default '' check (char_length(narration) <= 1000),
 voice text check (voice is null or char_length(voice) between 1 and 80),
 sfx_description text not null default '' check (char_length(sfx_description) <= 500),
 target_duration_ms integer not null default 4000 check (target_duration_ms between 500 and 60000),
 actual_duration_ms integer check (actual_duration_ms is null or actual_duration_ms between 0 and 600000),
 keyframe_asset_id bigint,
 audio_asset_id bigint,
 video_asset_id bigint,
 render_status text not null default 'pending' check (render_status in ('pending','queued','rendering','rendered','failed')),
 estimated_cost_cents numeric(14,4) not null default 0 check (estimated_cost_cents >= 0),
 actual_cost_cents numeric(14,4) not null default 0 check (actual_cost_cents >= 0),
 error text check (error is null or char_length(error) <= 4000),
 created_by uuid not null default auth.uid() references auth.users(id),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 unique (organization_id, id),
 constraint video_shots_position_unique unique (plan_id, position) deferrable initially deferred,
 foreign key (organization_id, keyframe_asset_id) references public.assets(organization_id, id) on delete set null (keyframe_asset_id),
 foreign key (organization_id, audio_asset_id) references public.assets(organization_id, id) on delete set null (audio_asset_id),
 foreign key (organization_id, video_asset_id) references public.assets(organization_id, id) on delete set null (video_asset_id),
 foreign key (organization_id, plan_id) references public.video_plans(organization_id, id) on delete cascade
);
comment on table public.video_shots is '分镜镜头。内容列由人编辑；render_status/资产引用/实际时长/成本由 worker 回写。';

create table public.video_storyboard_proposals (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null references public.organizations(id) on delete cascade,
 agent_job_id uuid not null,
 project_id uuid,
 input_outline text not null check (char_length(input_outline) between 1 and 20000),
 proposal jsonb not null check (jsonb_typeof(proposal) = 'object' and jsonb_typeof(proposal->'shots') = 'array' and pg_column_size(proposal) <= 262144),
 model text check (model is null or char_length(model) <= 128),
 status text not null default 'pending' check (status in ('pending','accepted','rejected')),
 accepted_plan_id uuid,
 decided_by uuid references auth.users(id) on delete set null,
 decided_at timestamptz,
 reason text not null default '' check (char_length(reason) <= 2000),
 created_at timestamptz not null default now(),
 unique (organization_id, id),
 unique (agent_job_id),
 foreign key (organization_id, agent_job_id) references public.agent_jobs(organization_id, id) on delete cascade,
 foreign key (organization_id, project_id) references public.content_projects(organization_id, id),
 foreign key (organization_id, accepted_plan_id) references public.video_plans(organization_id, id) on delete set null (accepted_plan_id)
);
comment on table public.video_storyboard_proposals is 'Agent 分镜拆解提案。只有人通过 accept_video_storyboard_proposal 才会写入 video_plans/video_shots。';

alter table public.video_plans add constraint video_plans_source_proposal_fkey
 foreign key (organization_id, source_proposal_id) references public.video_storyboard_proposals(organization_id, id) on delete set null (source_proposal_id);

create table public.video_cost_entries (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null,
 plan_id uuid not null,
 shot_id uuid,
 agent_job_id uuid,
 kind text not null check (kind in ('tts','shot_render','compose','keyframe','storyboard_llm')),
 provider text not null check (char_length(provider) between 1 and 64),
 estimated_cents numeric(14,4) not null default 0 check (estimated_cents >= 0),
 actual_cents numeric(14,4) not null default 0 check (actual_cents >= 0),
 metadata jsonb not null default '{}'::jsonb check (jsonb_typeof(metadata) = 'object'),
 created_at timestamptz not null default now(),
 foreign key (organization_id, plan_id) references public.video_plans(organization_id, id) on delete cascade,
 foreign key (organization_id, shot_id) references public.video_shots(organization_id, id) on delete set null (shot_id),
 foreign key (organization_id, agent_job_id) references public.agent_jobs(organization_id, id) on delete set null (agent_job_id)
);
comment on table public.video_cost_entries is '视频成本账本（追加写入，不可修改）。镜头与计划的实际成本由此汇总。';
create unique index video_cost_entries_job_once on public.video_cost_entries
 (agent_job_id, kind, coalesce(shot_id, '00000000-0000-0000-0000-000000000000'::uuid)) where agent_job_id is not null;

